∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
  {R : Breakdown.CertCell.CellCalculus.CellCalculusEntry D} {e : ℝ} {T : Breakdown.CertCell.TreeEntry D R},
  Breakdown.CertCell.CellJunctions D R e T → Breakdown.CertCell.PressureRecovered D

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {w₀ epsSup epsGradSup ratio : ℝ} {B : Breakdown.CertCell.TailBand.SetPieceBounds C nE nM} {mm : ℕ} {I : Set (ℤ × ℤ)}
  {Z : Set (ℝ × ℝ)} {ι : ℤ × ℤ} {p : ℝ × ℝ},
  Breakdown.CoerciveWeak.IsAdmissibleWeak m P h w W HW w₀ epsSup epsGradSup ratio →
    B.IsValidOn m P h mm I Z →
      ι ∈ I →
        p ∈ Z →
          B.curlLow m h p ≤
            m.coefA P h (Breakdown.CertCell.labelHarmonic mm ι) (Breakdown.CertCell.planePoint p) -
              m.convZ (m.classOf (Breakdown.CertCell.labelHarmonic mm ι)) (Breakdown.CertCell.planePoint p)

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {w₀ epsSup epsGradSup ratio : ℝ},
  Breakdown.CoerciveWeak.IsAdmissibleWeak m P h w W HW w₀ epsSup epsGradSup ratio →
    ∀ (T : Set (ℤ × ℤ)) (ξ : ℤ × ℤ) (y : Breakdown.Space), 0 ≤ Breakdown.PieceWeights.inward h T h.ampGradW ξ y

∀ {mesh : Breakdown.CertCell.ScalarShape.RationalMesh} {degT degX : ℕ}
  {coef : List (List (List (List Breakdown.CertCell.ScalarShape.Frac)))}
  {mesh_1 : Breakdown.CertCell.ScalarShape.RationalMesh} {degT_1 degX_1 : ℕ}
  {coef_1 : List (List (List (List Breakdown.CertCell.ScalarShape.Frac)))},
  { mesh := mesh, degT := degT, degX := degX, coef := coef } =
      { mesh := mesh_1, degT := degT_1, degX := degX_1, coef := coef_1 } →
    mesh = mesh_1 ∧ degT = degT_1 ∧ degX = degX_1 ∧ coef = coef_1

∀ {modes : Set (ℤ × ℤ)} {weight : Breakdown.CertCell.ScalarShape.CoefficientScalar}
  {share t4 : Breakdown.CertCell.ScalarShape.StepValues} {eta : ℝ} {modes_1 : Set (ℤ × ℤ)}
  {weight_1 : Breakdown.CertCell.ScalarShape.CoefficientScalar}
  {share_1 t4_1 : Breakdown.CertCell.ScalarShape.StepValues} {eta_1 : ℝ},
  { modes := modes, weight := weight, share := share, t4 := t4, eta := eta } =
      { modes := modes_1, weight := weight_1, share := share_1, t4 := t4_1, eta := eta_1 } →
    modes = modes_1 ∧ weight = weight_1 ∧ share = share_1 ∧ t4 = t4_1 ∧ eta = eta_1

∀ {k : ℕ} {C : Type} {nE nM : ℕ} {D : Breakdown.CertCell.CellLayerData k C nE nM}
