∀ {C : Type} {nE nM : ℕ} {chart : Breakdown.CellCert.GivenFields.ChartParams}
  {centralRadius : Breakdown.CertCell.ScalarShape.Frac} {classOf : ℤ × ℤ → C}
  {strainWeight vorticityWeight : C → Breakdown.CertCell.ScalarShape.CoefficientScalar}
  {eps : Fin nE → Breakdown.CertCell.ScalarShape.EpsValues} {mu : Fin nM → Breakdown.CertCell.ScalarShape.MuValues}
  {c cμ : ℝ} {chart_1 : Breakdown.CellCert.GivenFields.ChartParams}
  {centralRadius_1 : Breakdown.CertCell.ScalarShape.Frac} {classOf_1 : ℤ × ℤ → C}
  {strainWeight_1 vorticityWeight_1 : C → Breakdown.CertCell.ScalarShape.CoefficientScalar}
  {eps_1 : Fin nE → Breakdown.CertCell.ScalarShape.EpsValues} {mu_1 : Fin nM → Breakdown.CertCell.ScalarShape.MuValues}
  {c_1 cμ_1 : ℝ},
  { chart := chart, centralRadius := centralRadius, classOf := classOf, strainWeight := strainWeight,
        vorticityWeight := vorticityWeight, eps := eps, mu := mu, c := c, cμ := cμ } =
      { chart := chart_1, centralRadius := centralRadius_1, classOf := classOf_1, strainWeight := strainWeight_1,
        vorticityWeight := vorticityWeight_1, eps := eps_1, mu := mu_1, c := c_1, cμ := cμ_1 } →
    chart = chart_1 ∧
      centralRadius = centralRadius_1 ∧
        classOf = classOf_1 ∧
          strainWeight = strainWeight_1 ∧
            vorticityWeight = vorticityWeight_1 ∧ eps = eps_1 ∧ mu = mu_1 ∧ c = c_1 ∧ cμ = cμ_1

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ (ξ : ℤ × ℤ), ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (Breakdown.cnormSq (Breakdown.modeVel ξ v 0 y) ^ 3) < ⊤

∀ {mesh : Breakdown.CertCell.ScalarShape.RationalMesh} {upper lower : List (List Breakdown.CertCell.ScalarShape.Frac)}
  {decay : ℤ} {mesh_1 : Breakdown.CertCell.ScalarShape.RationalMesh}
  {upper_1 lower_1 : List (List Breakdown.CertCell.ScalarShape.Frac)} {decay_1 : ℤ},
  { mesh := mesh, upper := upper, lower := lower, decay := decay } =
      { mesh := mesh_1, upper := upper_1, lower := lower_1, decay := decay_1 } →
    mesh = mesh_1 ∧ upper = upper_1 ∧ lower = lower_1 ∧ decay = decay_1

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∫⁻ (σ : ℝ) in Set.Icc 0 1, ∫⁻ (y : Breakdown.Space), ENNReal.ofReal (‖v σ y‖ ^ 2 / (1 + ‖y‖) ^ 6) < ⊤

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ {ξ : ℤ × ℤ},
      ξ.2 = 0 →
        ∀ᵐ (y : Breakdown.Space),
          ∀ (ψ : ℝ),
            Breakdown.modeVel ξ v 0 (Breakdown.axialRot ψ y) = Breakdown.Coercive.rotC ψ (Breakdown.modeVel ξ v 0 y)

