∀ {E : Type u_1} [inst : NormedAddCommGroup E] [NormedSpace ℝ E] {f : Breakdown.Space → E} {K K' : ℝ}
  {s : Set Breakdown.Space},
  Breakdown.CertCell.GivenShape.Internal.SlopeOn f K s → K ≤ K' → Breakdown.CertCell.GivenShape.Internal.SlopeOn f K' s

∀ {W : ℝ → Breakdown.Space → Breakdown.Space}
  {HW : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space} {D : ℝ},
  Breakdown.CoerciveWeak.IsWeakSecondDerivState W HW D →
    ∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
      {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
      {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
      {g : ℝ → Breakdown.Space → Breakdown.Space},
      Breakdown.IsPerturbation Γ P v G H g →
        MeasureTheory.Integrable (fun z => Breakdown.CoerciveWeak.stretchFormWith W HW v G z.1 z.2)
          ((MeasureTheory.volume.restrict (Set.Icc 0 1)).prod MeasureTheory.volume)

∀ (a : Breakdown.CertCell.ModeCoefficients),
  Breakdown.CertCell.TailBand.PointCoef.ofMode a =
    { hess := a.hess, curlGrad := a.curlHess, curl := a.curl, grad := a.strain, vel := a.velocity, cross := 0 }

